// Program.cs
builder.Services.AddDbContext<AppDbContext>(options =>
{
    options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection"),
        sqlOptions =>
        {
            sqlOptions.EnableRetryOnFailure(
                maxRetryCount: 5,
                maxRetryDelay: TimeSpan.FromSeconds(30),
                errorNumbersToAdd: null);
            sqlOptions.CommandTimeout(60);
        });
    options.EnableSensitiveDataLogging(builder.Environment.IsDevelopment());
    options.EnableDetailedErrors();
});

// DbContext class
public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Product> Products => Set<Product>();
    public DbSet<Category> Categories => Set<Category>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(AppDbContext).Assembly);
        base.OnModelCreating(modelBuilder);
    }
}

// Program.cs
builder.Services.AddDbContextPool<AppDbContext>(options =>
{
    options.UseSqlServer(connectionString);
}, poolSize: 128);

// How it works:
// - Pool maintains reusable DbContext instances
// - Much faster than creating new instances
// - Must NOT store DbContext in a field (it gets returned to pool)
// - Only for stateless DbContext usage

// Correct usage (scoped)
public class ProductService(AppDbContext db)
{
    public async Task<List<Product>> GetAllAsync()
        => await db.Products.ToListAsync();
}

// WRONG: storing DbContext
public class BadService
{
    private readonly AppDbContext _db; // Gets returned to pool while still in use!
    public BadService(AppDbContext db) => _db = db;
}
